-- Function: public.fn_get_harvest_monthly_metrics
-- Backup generated on 2026-10-25 20:33:24

CREATE OR REPLACE FUNCTION public.fn_get_harvest_monthly_metrics(p_tenant_id uuid)  RETURNS TABLE(total_experiences integer, total_feedbacks integer)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT         (SELECT COUNT(*)::INT           FROM experience_schedules es           WHERE es.tenant_id = p_tenant_id             AND EXTRACT(MONTH FROM es.scheduled_date) = EXTRACT(MONTH FROM CURRENT_DATE)             AND EXTRACT(YEAR FROM es.scheduled_date) = EXTRACT(YEAR FROM CURRENT_DATE)) AS total_experiences,         (SELECT COUNT(*)::INT           FROM experience_feedback f          JOIN experience_schedules s ON f.experience_schedule_id = s.id          WHERE f.tenant_id = p_tenant_id             AND EXTRACT(MONTH FROM s.scheduled_date) = EXTRACT(MONTH FROM CURRENT_DATE)             AND EXTRACT(YEAR FROM s.scheduled_date) = EXTRACT(YEAR FROM CURRENT_DATE)) AS total_feedbacks; END; $function$ ;
